 item jsonb;target oid;actual pg_catalog.pg_proc%rowtype;after_row pg_catalog.pg_proc%rowtype;
 snapshots jsonb:='[]'::jsonb;expected jsonb;entry jsonb;definition text;desired text;
 phase text;profile text;expected_owner text;expected_config text[];pname text;required_table text;
 patch jsonb;raw_body bytea;patch_bytes bytea;patch_offset integer;patch_length integer;previous_offset integer;source_item jsonb;source_row pg_catalog.pg_proc%rowtype;
 authority_namespaces jsonb;authority_roles jsonb;authority_memberships jsonb;temporary_public_create boolean:=false;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres' OR session_user IS DISTINCT FROM 'postgres'
  OR current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999
  OR(SELECT rolsuper FROM pg_roles WHERE rolname=current_user) IS DISTINCT FROM false
  THEN RAISE EXCEPTION 'crosspath_forward_qualified_pg17_nosuper_postgres_required';END IF;
 -- Snapshot exact namespace ACL/owners and complete existing roles/memberships.
 SELECT jsonb_agg(to_jsonb(n) ORDER BY n.oid) INTO authority_namespaces FROM pg_namespace n WHERE n.nspname IN('public','gridex_ediel_retention');
 SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) INTO authority_roles FROM pg_roles r;
 SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.roleid,m.member,m.grantor),'[]'::jsonb) INTO authority_memberships FROM pg_auth_members m;
 IF pg_has_role('postgres','gridex_ediel_retention_owner','MEMBER') IS DISTINCT FROM true
  OR pg_has_role('postgres','gridex_ediel_retention_owner','SET') IS DISTINCT FROM true
  OR has_schema_privilege('gridex_ediel_retention_owner','gridex_ediel_retention','CREATE') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'crosspath_forward_existing_owner_set_authority_required';END IF;
 -- Establish one coherent pair and first/replay phase before any DDL.
 FOR item IN SELECT value FROM jsonb_array_elements(config) WHERE value->>'role'='public' AND value->>'kind'='finalize' LOOP
  SELECT * INTO STRICT actual FROM pg_proc WHERE oid=to_regprocedure(item->>'signature');
  IF md5(actual.prosrc)=item->'pins'->>'native' AND encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex')=body_pins->(item->'pins'->>'native')->>'sha256' THEN phase:='first';profile:='native';
  ELSIF md5(actual.prosrc)=item->'pins'->>'canonical' AND encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex')=body_pins->(item->'pins'->>'canonical')->>'sha256' THEN phase:='first';profile:='canonical';
  ELSIF md5(actual.prosrc)=item->'pins'->>'target_native' AND encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex')=body_pins->(item->'pins'->>'target_native')->>'sha256' THEN phase:='replay';profile:='native';
  ELSIF md5(actual.prosrc)=item->'pins'->>'target_canonical' AND encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex')=body_pins->(item->'pins'->>'target_canonical')->>'sha256' THEN phase:='replay';profile:='canonical';
  ELSE RAISE EXCEPTION 'crosspath_forward_unknown_finalizer_profile';END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(config) LOOP
  target:=to_regprocedure(item->>'signature');SELECT * INTO STRICT actual FROM pg_proc WHERE oid=target;
  pname:=CASE WHEN phase='replay' THEN 'target_'||profile ELSE profile END;
  IF md5(actual.prosrc) IS DISTINCT FROM item->'pins'->>pname
   OR encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex') IS DISTINCT FROM body_pins->(item->'pins'->>pname)->>'sha256'
   OR octet_length(convert_to(actual.prosrc,'UTF8')) IS DISTINCT FROM(body_pins->(item->'pins'->>pname)->>'bytes')::integer
   THEN RAISE EXCEPTION 'crosspath_forward_unknown_or_mixed_body:%',item->>'signature';END IF;
  desired:=actual.prosrc;
  expected_owner:=coalesce(item->>'owner','postgres');
  expected_config:=CASE WHEN item->>'role' IN('retention','helper') OR item->>'signature' LIKE 'public.gridex_prepare_customer%' OR item->>'role'='public' AND(profile='canonical' OR phase='replay') THEN ARRAY['search_path=pg_catalog']::text[] WHEN item->>'kind'='prepare' THEN ARRAY['search_path=public, private, extensions, pg_temp']::text[] ELSE ARRAY['search_path=public, extensions, pg_temp']::text[] END;
  expected:=(common_metadata||(item->'template'))-'oid'-'prosrc'-'proowner'-'prolang'-'pronamespace'-'proconfig';
  IF(to_jsonb(actual)-'oid'-'prosrc'-'proowner'-'prolang'-'pronamespace'-'proconfig') IS DISTINCT FROM expected
   OR pg_get_userbyid(actual.proowner) IS DISTINCT FROM expected_owner
   OR(SELECT lanname FROM pg_language WHERE oid=actual.prolang) IS DISTINCT FROM 'plpgsql'
   OR actual.pronamespace IS DISTINCT FROM split_part(item->>'signature','.',1)::regnamespace
   OR actual.proconfig IS DISTINCT FROM expected_config OR actual.proacl IS NULL
   THEN RAISE EXCEPTION 'crosspath_forward_unknown_full_metadata:%',item->>'signature';END IF;
  definition:=pg_get_functiondef(target);IF strpos(definition,actual.prosrc)=0 THEN RAISE EXCEPTION 'crosspath_forward_definition_unknown';END IF;
  snapshots:=snapshots||jsonb_build_array(jsonb_build_object('oid',target,'signature',item->>'signature','role',item->>'role','row',to_jsonb(actual),'definition',definition,'desired',desired));
 END LOOP;
 -- All nine source rows/metadata have passed. Reconstruct changed bodies only.
 FOR item IN SELECT value FROM jsonb_array_elements(config) WHERE value->>'role' IN('public','retention') LOOP
  SELECT value INTO STRICT entry FROM jsonb_array_elements(snapshots) WHERE value->>'signature'=item->>'signature';
  raw_body:=convert_to(entry->'row'->>'prosrc','UTF8');
  IF phase='first' THEN
   IF profile='canonical' AND item->>'role'='public' THEN
    SELECT value INTO STRICT source_item FROM jsonb_array_elements(config) WHERE value->>'signature'=item->>'canonicalSource';
    SELECT * INTO STRICT source_row FROM pg_proc WHERE oid=to_regprocedure(item->>'canonicalSource');
    IF md5(source_row.prosrc) IS DISTINCT FROM source_item->'pins'->>'canonical'
     OR encode(sha256(convert_to(source_row.prosrc,'UTF8')),'hex') IS DISTINCT FROM body_pins->(source_item->'pins'->>'canonical')->>'sha256'
     THEN RAISE EXCEPTION 'crosspath_forward_canonical_source_core_changed';END IF;
    raw_body:=convert_to(source_row.prosrc,'UTF8');
   END IF;
   previous_offset:=octet_length(raw_body)+1;
   FOR patch IN SELECT value FROM jsonb_array_elements(item->'patches') LOOP
    patch_offset:=(patch->>'offset')::integer;patch_length:=(patch->>'oldBytes')::integer;
    IF patch_offset<0 OR patch_length<0 OR patch_offset+patch_length>previous_offset
     OR patch_offset+patch_length>octet_length(raw_body)
     OR encode(sha256(substring(raw_body FROM patch_offset+1 FOR patch_length)),'hex') IS DISTINCT FROM patch->>'oldSha256'
     THEN RAISE EXCEPTION 'crosspath_forward_exact_patch_fragment_required';END IF;
    patch_bytes:=convert_to((CASE WHEN patch ? 'shared' THEN replace(shared_replacements->>(patch->>'shared'),'@row_lock@',coalesce(patch->>'rowLock','')) ELSE patch->>'replacement' END),'UTF8');
    raw_body:=overlay(raw_body PLACING patch_bytes FROM patch_offset+1 FOR patch_length);
    previous_offset:=patch_offset;
   END LOOP;
  END IF;
  desired:=convert_from(raw_body,'UTF8');pname:='target_'||profile;
  IF md5(desired) IS DISTINCT FROM item->'pins'->>pname
   OR encode(sha256(raw_body),'hex') IS DISTINCT FROM body_pins->(item->'pins'->>pname)->>'sha256'
   OR octet_length(raw_body) IS DISTINCT FROM(body_pins->(item->'pins'->>pname)->>'bytes')::integer
   THEN RAISE EXCEPTION 'crosspath_forward_complete_target_body_required';END IF;
  snapshots:=(SELECT jsonb_agg(CASE WHEN value->>'signature'=item->>'signature' THEN jsonb_set(value,'{desired}',to_jsonb(desired)) ELSE value END ORDER BY ordinality) FROM jsonb_array_elements(snapshots) WITH ORDINALITY);
 END LOOP;
 -- Exact existing effective authority, never grants. Row locking needs UPDATE.
 IF(SELECT rolbypassrls FROM pg_roles WHERE rolname='gridex_ediel_retention_owner') IS DISTINCT FROM true
  OR(SELECT rolsuper FROM pg_roles WHERE rolname='gridex_ediel_retention_owner') IS DISTINCT FROM false
  OR(SELECT rolcanlogin FROM pg_roles WHERE rolname='gridex_ediel_retention_owner') IS DISTINCT FROM false
  OR(SELECT rolinherit FROM pg_roles WHERE rolname='gridex_ediel_retention_owner') IS DISTINCT FROM false
  OR has_function_privilege('postgres','public.ediel_require_contract_records_available_v1(uuid,uuid)','EXECUTE') IS DISTINCT FROM true
  OR has_schema_privilege('gridex_ediel_retention_owner','public','USAGE') IS DISTINCT FROM true
  OR has_schema_privilege('gridex_ediel_retention_owner','gridex_ediel_retention','USAGE') IS DISTINCT FROM true
  OR has_table_privilege('gridex_ediel_retention_owner','gridex_ediel_retention.record_tombstones','SELECT') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'crosspath_forward_retained_authority_unavailable';END IF;
 FOREACH required_table IN ARRAY ARRAY['public.customer_contracts','public.customers','public.customer_contract_documents','public.customer_contract_signature_requests','public.customer_contract_acceptances','public.customer_contract_evidence','public.customer_addresses','public.customer_portal_events','public.customer_portal_api_access_logs','public.customer_events','public.domain_events','public.customer_legal_acceptances','public.customer_onboarding_legal_snapshots'] LOOP
  IF has_table_privilege('gridex_ediel_retention_owner',required_table,'SELECT') IS DISTINCT FROM true OR has_table_privilege('gridex_ediel_retention_owner',required_table,'UPDATE') IS DISTINCT FROM true THEN RAISE EXCEPTION 'crosspath_forward_retention_lock_authority_unavailable:%',required_table;END IF;
 END LOOP;
 FOREACH required_table IN ARRAY ARRAY['public.companies','public.customer_contracts','public.customer_contract_signature_requests'] LOOP
  IF has_table_privilege('postgres',required_table,'SELECT') IS DISTINCT FROM true OR has_table_privilege('postgres',required_table,'UPDATE') IS DISTINCT FROM true THEN RAISE EXCEPTION 'crosspath_forward_signing_lock_authority_unavailable:%',required_table;END IF;
 END LOOP;
 -- Temporary existing-source authority only: no permanent schema grant.
 IF phase='first' AND has_schema_privilege('gridex_ediel_retention_owner','public','CREATE') IS DISTINCT FROM true THEN
  IF(SELECT nspacl FROM pg_namespace WHERE nspname='public') IS NULL
   OR has_schema_privilege('postgres','public','CREATE WITH GRANT OPTION') IS DISTINCT FROM true
   THEN RAISE EXCEPTION 'crosspath_forward_temporary_public_create_not_exactly_restorable';END IF;
  GRANT CREATE ON SCHEMA public TO gridex_ediel_retention_owner;
  temporary_public_create:=true;
 END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(snapshots) LOOP
  IF phase='first' AND entry->>'role' IN('public','retention') THEN
   IF entry->>'role'='retention' THEN EXECUTE 'SET LOCAL ROLE gridex_ediel_retention_owner';END IF;
   IF entry->>'desired' IS DISTINCT FROM entry->'row'->>'prosrc' THEN EXECUTE replace(entry->>'definition',entry->'row'->>'prosrc',entry->>'desired');END IF;
   IF entry->>'role'='retention' THEN EXECUTE 'SET LOCAL ROLE postgres';END IF;
   IF entry->>'role'='public' THEN EXECUTE format('ALTER FUNCTION %s SET search_path TO pg_catalog',entry->>'signature');END IF;
  END IF;
 END LOOP;
 IF current_user IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'crosspath_forward_role_not_restored';END IF;
 IF temporary_public_create THEN REVOKE CREATE ON SCHEMA public FROM gridex_ediel_retention_owner;END IF;
 IF(SELECT jsonb_agg(to_jsonb(n) ORDER BY n.oid) FROM pg_namespace n WHERE n.nspname IN('public','gridex_ediel_retention')) IS DISTINCT FROM authority_namespaces
  OR(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_roles r) IS DISTINCT FROM authority_roles
  OR(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.roleid,m.member,m.grantor),'[]'::jsonb) FROM pg_auth_members m) IS DISTINCT FROM authority_memberships
  THEN RAISE EXCEPTION 'crosspath_forward_namespace_or_role_authority_not_restored';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(snapshots) LOOP
  SELECT * INTO STRICT after_row FROM pg_proc WHERE oid=(entry->>'oid')::oid;
  IF entry->>'role' IN('public','retention') THEN
   IF(to_jsonb(after_row)-'prosrc'-'proconfig') IS DISTINCT FROM((entry->'row')-'prosrc'-'proconfig')
    OR after_row.prosrc IS DISTINCT FROM entry->>'desired'
    OR after_row.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog']::text[] THEN RAISE EXCEPTION 'crosspath_forward_final_changed_protected_metadata';END IF;
  ELSE
   IF to_jsonb(after_row) IS DISTINCT FROM entry->'row' OR pg_get_functiondef(after_row.oid) IS DISTINCT FROM entry->>'definition' THEN RAISE EXCEPTION 'crosspath_forward_changed_protected_core_or_helper';END IF;
  END IF;
  IF phase='replay' AND(to_jsonb(after_row) IS DISTINCT FROM entry->'row' OR pg_get_functiondef(after_row.oid) IS DISTINCT FROM entry->>'definition') THEN RAISE EXCEPTION 'crosspath_forward_replay_changed_full_row';END IF;
 END LOOP;
END
$crosspath_forward$;
COMMIT;
